CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_self_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profile_self_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_beauty_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'name','')); RETURN NEW; END $$;
CREATE TRIGGER beauty_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_beauty_profile();
CREATE TABLE public.companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.companies TO authenticated; GRANT ALL ON public.companies TO service_role;
ALTER TABLE public.companies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, company_id uuid NOT NULL REFERENCES public.companies(id), role text NOT NULL CHECK(role IN ('owner','client')), UNIQUE(user_id,company_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_self ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.owns_company(cid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND company_id=cid AND role='owner') $$;
CREATE FUNCTION public.belongs_company(cid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND company_id=cid) $$;
CREATE POLICY company_members ON public.companies FOR SELECT TO authenticated USING(public.belongs_company(id));
CREATE TABLE public.clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), user_id uuid, name text NOT NULL, phone text NOT NULL DEFAULT '', points integer NOT NULL DEFAULT 0 CHECK(points>=0), invite_token uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,user_id));
GRANT SELECT ON public.clients TO authenticated; GRANT ALL ON public.clients TO service_role;
ALTER TABLE public.clients ENABLE ROW LEVEL SECURITY;
CREATE POLICY clients_owner ON public.clients FOR SELECT TO authenticated USING(public.owns_company(company_id));
CREATE POLICY clients_self ON public.clients FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.loyalty_rewards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), name text NOT NULL, description text NOT NULL DEFAULT '', points integer NOT NULL CHECK(points>0), kind text NOT NULL DEFAULT 'service' CHECK(kind IN ('service','product')), active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.loyalty_rewards TO authenticated; GRANT ALL ON public.loyalty_rewards TO service_role;
ALTER TABLE public.loyalty_rewards ENABLE ROW LEVEL SECURITY;
CREATE POLICY rewards_members ON public.loyalty_rewards FOR SELECT TO authenticated USING(public.belongs_company(company_id));
CREATE TABLE public.booking_slots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), starts_at timestamptz NOT NULL, booked boolean NOT NULL DEFAULT false, UNIQUE(company_id,starts_at));
GRANT SELECT ON public.booking_slots TO authenticated; GRANT ALL ON public.booking_slots TO service_role;
ALTER TABLE public.booking_slots ENABLE ROW LEVEL SECURITY;
CREATE POLICY slots_members ON public.booking_slots FOR SELECT TO authenticated USING(public.belongs_company(company_id));
CREATE TABLE public.reward_redemptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), client_id uuid NOT NULL REFERENCES public.clients(id), reward_id uuid NOT NULL REFERENCES public.loyalty_rewards(id), slot_id uuid NOT NULL UNIQUE REFERENCES public.booking_slots(id), reward_name text NOT NULL, points_spent integer NOT NULL, coupon_code text NOT NULL UNIQUE DEFAULT upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)), status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','used')), created_at timestamptz NOT NULL DEFAULT now(), used_at timestamptz);
GRANT SELECT ON public.reward_redemptions TO authenticated; GRANT ALL ON public.reward_redemptions TO service_role;
ALTER TABLE public.reward_redemptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY redemptions_owner ON public.reward_redemptions FOR SELECT TO authenticated USING(public.owns_company(company_id));
CREATE POLICY redemptions_self ON public.reward_redemptions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.clients c WHERE c.id=client_id AND c.user_id=auth.uid()));
CREATE INDEX client_user_idx ON public.clients(user_id); CREATE INDEX redemption_company_idx ON public.reward_redemptions(company_id); CREATE INDEX slot_company_idx ON public.booking_slots(company_id,starts_at);
CREATE FUNCTION public.setup_beauty_company(studio_name text, owner_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Account already assigned'; END IF; IF length(trim(studio_name))<2 OR length(trim(owner_name))<2 THEN RAISE EXCEPTION 'Name required'; END IF; INSERT INTO public.companies(name) VALUES(trim(studio_name)) RETURNING id INTO cid; INSERT INTO public.user_roles(user_id,company_id,role) VALUES(auth.uid(),cid,'owner'); UPDATE public.profiles SET name=trim(owner_name) WHERE id=auth.uid(); RETURN cid; END $$;
CREATE FUNCTION public.create_beauty_client(cid uuid, client_name text, client_phone text, initial_points integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.owns_company(cid) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF length(trim(client_name))<2 OR initial_points<0 THEN RAISE EXCEPTION 'Invalid client'; END IF; INSERT INTO public.clients(company_id,name,phone,points) VALUES(cid,trim(client_name),client_phone,initial_points) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.join_beauty_client(token uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.clients; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; SELECT * INTO c FROM public.clients WHERE invite_token=token FOR UPDATE; IF c.id IS NULL OR (c.user_id IS NOT NULL AND c.user_id<>auth.uid()) THEN RAISE EXCEPTION 'Invalid invitation'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND (company_id<>c.company_id OR role<>'client')) THEN RAISE EXCEPTION 'Account already assigned'; END IF; UPDATE public.clients SET user_id=auth.uid() WHERE id=c.id; INSERT INTO public.user_roles(user_id,company_id,role) VALUES(auth.uid(),c.company_id,'client') ON CONFLICT(user_id,company_id) DO NOTHING; RETURN c.company_id; END $$;
CREATE FUNCTION public.set_beauty_points(client uuid, balance integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN SELECT company_id INTO cid FROM public.clients WHERE id=client; IF NOT coalesce(public.owns_company(cid),false) OR balance<0 THEN RAISE EXCEPTION 'Forbidden or invalid balance'; END IF; UPDATE public.clients SET points=balance WHERE id=client; END $$;
CREATE FUNCTION public.create_beauty_reward(cid uuid, reward_name text, reward_description text, cost integer, reward_kind text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.owns_company(cid) OR length(trim(reward_name))<2 OR cost<=0 OR reward_kind NOT IN ('service','product') THEN RAISE EXCEPTION 'Forbidden or invalid reward'; END IF; INSERT INTO public.loyalty_rewards(company_id,name,description,points,kind) VALUES(cid,trim(reward_name),reward_description,cost,reward_kind); END $$;
CREATE FUNCTION public.create_beauty_slot(cid uuid, slot_time timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.owns_company(cid) OR slot_time<=now() THEN RAISE EXCEPTION 'Forbidden or invalid time'; END IF; INSERT INTO public.booking_slots(company_id,starts_at) VALUES(cid,slot_time); END $$;
CREATE FUNCTION public.redeem_beauty_reward(reward uuid, slot uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.loyalty_rewards; c public.clients; s public.booking_slots; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; SELECT * INTO r FROM public.loyalty_rewards WHERE id=reward AND active; IF r.id IS NULL THEN RAISE EXCEPTION 'Reward unavailable'; END IF; SELECT * INTO c FROM public.clients WHERE company_id=r.company_id AND user_id=auth.uid() FOR UPDATE; IF c.id IS NULL OR c.points<r.points THEN RAISE EXCEPTION 'Insufficient points'; END IF; SELECT * INTO s FROM public.booking_slots WHERE id=slot AND company_id=r.company_id FOR UPDATE; IF s.id IS NULL OR s.booked OR s.starts_at<=now() THEN RAISE EXCEPTION 'Slot unavailable'; END IF; UPDATE public.clients SET points=points-r.points WHERE id=c.id; UPDATE public.booking_slots SET booked=true WHERE id=s.id; INSERT INTO public.reward_redemptions(company_id,client_id,reward_id,slot_id,reward_name,points_spent) VALUES(r.company_id,c.id,r.id,s.id,r.name,r.points) RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.use_beauty_coupon(redemption uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN SELECT company_id INTO cid FROM public.reward_redemptions WHERE id=redemption; IF NOT coalesce(public.owns_company(cid),false) THEN RAISE EXCEPTION 'Forbidden'; END IF; UPDATE public.reward_redemptions SET status='used',used_at=now() WHERE id=redemption AND status='scheduled'; END $$;
REVOKE ALL ON FUNCTION public.create_beauty_profile() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.owns_company(uuid),public.belongs_company(uuid),public.setup_beauty_company(text,text),public.create_beauty_client(uuid,text,text,integer),public.join_beauty_client(uuid),public.set_beauty_points(uuid,integer),public.create_beauty_reward(uuid,text,text,integer,text),public.create_beauty_slot(uuid,timestamptz),public.redeem_beauty_reward(uuid,uuid),public.use_beauty_coupon(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.owns_company(uuid),public.belongs_company(uuid),public.setup_beauty_company(text,text),public.create_beauty_client(uuid,text,text,integer),public.join_beauty_client(uuid),public.set_beauty_points(uuid,integer),public.create_beauty_reward(uuid,text,text,integer,text),public.create_beauty_slot(uuid,timestamptz),public.redeem_beauty_reward(uuid,uuid),public.use_beauty_coupon(uuid) TO authenticated;